import { execFileSync } from 'node:child_process';
const file = process.argv[2];
const mode = process.argv[3] || 'sum';
const raw = execFileSync('git', ['show', `origin/conversation-logs:${file}`], { cwd: '/home/user/Claudinite', maxBuffer: 1 << 30 }).toString();
const entries = raw.split('\n').filter(Boolean).map(l => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean);
const t0 = new Date(entries[0]?.timestamp), tN = new Date(entries[entries.length - 1]?.timestamp);
// tool_use id -> {name, ts}
const uses = new Map();
const durs = [];
const errs = [];
const userText = [];
for (const e of entries) {
  const m = e.message;
  const ts = e.timestamp ? new Date(e.timestamp) : null;
  if (!m) continue;
  const content = Array.isArray(m.content) ? m.content : (typeof m.content === 'string' ? [{ type: 'text', text: m.content }] : []);
  for (const c of content) {
    if (c.type === 'tool_use') uses.set(c.id, { name: c.name, ts, input: JSON.stringify(c.input).slice(0, 160) });
    if (c.type === 'tool_result') {
      const u = uses.get(c.tool_use_id);
      if (u && ts) durs.push({ name: u.name, s: (ts - u.ts) / 1000, input: u.input });
      const txt = typeof c.content === 'string' ? c.content : JSON.stringify(c.content);
      if (c.is_error || /error|Error|fatal|denied|not permitted/.test(txt || '')) errs.push({ name: u?.name, input: u?.input, t: (txt || '').slice(0, 200) });
    }
    if (c.type === 'text' && e.type === 'user' && !e.isMeta) userText.push(c.text.slice(0, 700));
  }
}
if (mode === 'sum') {
  const byName = {};
  for (const d of durs) { byName[d.name] ??= { n: 0, s: 0, max: 0 }; byName[d.name].n++; byName[d.name].s += d.s; byName[d.name].max = Math.max(byName[d.name].max, d.s); }
  console.log(`FILE ${file}`);
  console.log(`span ${((tN - t0) / 60000).toFixed(1)} min, ${entries.length} entries, ${durs.length} tool calls, total tool s=${durs.reduce((a, b) => a + b.s, 0).toFixed(0)}`);
  console.log('--- by tool (n, totalS, maxS) ---');
  for (const [k, v] of Object.entries(byName).sort((a, b) => b[1].s - a[1].s).slice(0, 12)) console.log(`  ${k}: n=${v.n} tot=${v.s.toFixed(0)}s max=${v.max.toFixed(0)}s`);
  console.log('--- slowest calls ---');
  for (const d of durs.sort((a, b) => b.s - a.s).slice(0, 8)) console.log(`  ${d.s.toFixed(0)}s ${d.name} ${d.input}`);
  console.log(`--- errors (${errs.length}) ---`);
  for (const e of errs.slice(0, 12)) console.log(`  ${e.name} ${e.input}\n    -> ${e.t.replace(/\n/g, ' ')}`);
  console.log(`--- user turns (${userText.length}) ---`);
  for (const u of userText) console.log('  >> ' + u.replace(/\n/g, ' | '));
}

